def maxValue(nums: List[int], k: int) -> int:
    n = len(nums)
    # dp_left[i][mask] stores the minimum possible maximum index 
    # of a subsequence of size i that results in OR sum 'mask'.
    dp_left = [[float('inf')] * 128 for _ in range(k + 1)]
    dp_left[0][0] = -1

    for j in range(n):
        val = nums[j]
        # Iterate backwards to ensure each element is used at most once per subsequence.
        for i in range(k, 0, -1):
            prev_dp = dp_left[i-1]
            curr_dp = dp_left[i]
            for m in range(128):
                if prev_dp[m] != float('inf'):
                    new_mask = m | val
                    # If we include nums[j], the max index of this subsequence is j.
                    # Because j increases, the first time we reach a mask with i 
                    # elements using nums[j], it's the minimum possible max index.
                    if j < curr_dp[new_mask]:
                        curr_dp[new_mask] = j

    # dp_right_rev handles the reversed array to find the maximum possible minimum index 
    # in the original array for a subsequence of size k.
    nums_rev = nums[::-1]
    dp_right_rev = [[float('inf')] * 128 for _ in range(k + 1)]
    dp_right_rev[0][0] = -1
    for j in range(n):
        val = nums_rev[j]
        for i in range(k, 0, -1):
            prev_dp = dp_right_rev[i-1]
            curr_dp = dp_right_rev[i]
            for m in range(128):
                if prev_dp[m] != float('inf'):
                    new_mask = m | val
                    # In the reversed array, minimizing the max index used 
                    # corresponds to maximizing the minimum original index.
                    if j < curr_dp[new_mask]:
                        curr_dp[new_mask] = j

    max_min_idx = [-1] * 128
    for m in range(128):
        if dp_right_rev[k][m] != float('inf'):
            # The max index in the reversed array corresponds to n-1 - (min index in original).
            max_min_idx[m] = n - 1 - dp_right_rev[k][m]

    ans = 0
    for m1 in range(128):
        if dp_left[k][m1] != float('inf'):
            for m2 in range(128):
                if max_min_idx[m2] != -1:
                    # For a valid subsequence of size 2*k, the first k elements' indices 
                    # must all be strictly smaller than the last k elements' indices.
                    # This is equivalent to saying the maximum index of the first half 
                    # is less than the minimum index of the second half.
                    if dp_left[k][m1] < max_min_idx[m2]:
                        res = m1 ^ m2
                        if res > ans:
                            ans = res
    return int(ans)

